// Recompiles contracts/XdevsBundlerGasMeter.sol with Foundry and regenerates src/gas-meter-artifact.ts.
// The generated file is committed so the bundler runs without Foundry. Usage: npm run build:meter
import { execFileSync } from 'node:child_process'
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const out = mkdtempSync(join(tmpdir(), 'xdevs-meter-'))
try {
  execFileSync(
    'forge',
    [
      'build', '--root', root, '--contracts', 'contracts', '--out', join(out, 'out'), '--cache-path', join(out, 'cache'),
      '--use', '0.8.38', '--optimize', '--optimizer-runs', '200', '--evm-version', 'cancun', '--no-metadata',
    ],
    { stdio: 'inherit' },
  )
  const art = JSON.parse(
    readFileSync(join(out, 'out', 'XdevsBundlerGasMeter.sol', 'XdevsBundlerGasMeter.json'), 'utf8'),
  ) as { bytecode: { object: string }; abi: unknown }
  const src = `// GENERATED by scripts/build-meter.ts from contracts/XdevsBundlerGasMeter.sol (solc 0.8.38, optimizer 200,
// evm cancun, no metadata). Do not edit by hand: run \`npm run build:meter\`.
export const GAS_METER_BYTECODE = '${art.bytecode.object}' as const
`
  writeFileSync(join(root, 'src', 'gas-meter-artifact.ts'), src)
  console.log('wrote src/gas-meter-artifact.ts', (art.bytecode.object.length - 2) / 2, 'bytes')
} finally {
  rmSync(out, { recursive: true, force: true })
}
